// Writes fresh chipnet TEST secrets to .env (gitignored). Never prints them.
import { existsSync, writeFileSync } from 'node:fs';
import { generateBip39Mnemonic, generatePrivateKey, binToHex } from '@bitauth/libauth';

if (existsSync('.env')) { console.log('.env already exists; not overwriting'); process.exit(0); }
const lines = [
  '# chipnet TEST secrets only. Generated by scripts/keygen.ts. Never use on mainnet.',
  `OWNER_MNEMONIC="${generateBip39Mnemonic()}"`,
  `PROVIDER_MNEMONIC="${generateBip39Mnemonic()}"`,
  `AGENT_PRIVKEY=${binToHex(generatePrivateKey())}`,
  '',
];
writeFileSync('.env', lines.join('\n'), { mode: 0o600 });
console.log('wrote .env (owner + provider mnemonics, agent key)');
